import{z as o,x as B,o as e,c as l,q as t,j as r,D as E,d as s,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"并发跳表","description":"","frontmatter":{"title":"并发跳表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/concurrent-skip-list.md","filePath":"cs/concurrent-skip-list.md","lastUpdated":1791063341000}'),p={name:"cs/concurrent-skip-list.md"};function d(c,a,h,C,D,S){const A=B("Mermaid");return e(),l("div",null,[a[2]||(a[2]=t('<h1 id="并发跳表" tabindex="-1">并发跳表 <a class="header-anchor" href="#并发跳表" aria-label="Permalink to &quot;并发跳表&quot;">​</a></h1><div class="epigraph"><p>跳表没有必须旋转的根；各层前向指针可以用 CAS 接线，查找甚至常常无锁只读。</p><footer>—— 据 Pugh, Concurrent Maintenance of Skip Lists, 1990；Herlihy and Shavit, The Art of Multiprocessor Programming 整理</footer></div><p><a href="/cs/order-statistic-tree">上一课</a>的树要旋转，旋转碰祖先，细粒度锁难。<a href="/cs/skip-list">跳表</a> 的形状是局部接线。<a href="/cs/lockfree-aba">无锁与 ABA</a> 已警告 CAS 位型。本课不重讲随机层高期望。缺口是并发跳表：查找无锁遍历，插入删除对前驱指针 CAS（或分层锁）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>共享有序映射：红黑全局锁太粗；无锁 BST 要帮旋转与 ABA。跳表层间独立：插入先串底层再从低到高挂快进指针；删除标记再解链。缺口是<strong>线性化点落在某层指针从旧后继改到新后继</strong>，查找要能容忍「看见正在插入的半成品」。</p><p><span class="marginnote">跳表可以想象成一套地铁线网：底层是站站停的慢车，往上每层是越跳越远的快车。查找就像规划路线——先在快车上跳过大片区间，快到站了再逐层「下车」补末端几站。层高随机决定的是这站停靠哪些快车线，与别的站无关，所以并发接线可以各站各改。</span></p><p><span class="marginnote">Java <code>ConcurrentSkipListMap</code> 是实践标杆之一。Pugh 1990 技术报告写了并发维护。Herlihy–Shavit 教材有整章跳表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：从高层向右向下，读指针；若实现用标记位表示「节点已删」，查找跳过标记节点。插入：找到每层前驱，CAS 前驱的 next；失败则重找。删除：先逻辑删（标记），再物理摘指针，避免查找走到野指针。</p>',9)),(e(),r(n,null,{default:E(()=>[i(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRCH%5B%22%E6%9F%A5%E6%89%BE%3A%20%E5%90%91%E5%8F%B3%E5%86%8D%E5%90%91%E4%B8%8B%22%5D%20--%3E%20READ%5B%22%E5%8F%AA%E8%AF%BB%E6%8C%87%E9%92%88%22%5D%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%22%5D%20--%3E%20CAS%5B%22CAS%20%E5%89%8D%E9%A9%B1%E7%9A%84%20next%22%5D%0A%20%20DEL%5B%22%E5%88%A0%E9%99%A4%22%5D%20--%3E%20MARK%5B%22%E6%A0%87%E8%AE%B0%E5%86%8D%E8%A7%A3%E9%93%BE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>与<a href="/cs/treap">Treap</a>：期望对数同类，并发时跳表少旋转。进度：无锁查找常见；插入可能锁或 CAS 重试，活锁要限次。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>层高仍插入时随机，与并发独立。ABA：节点复用时 next 或标记可能骗过 CAS，回收用 hazard / epoch，后课再钉，本课承认「节点不能立即重用」。<span class="marginnote">初学者容易以为删除后把节点还回分配器就完事，实际上别的线程可能还攥着这个节点的旧指针正要 CAS——地址一被复用，CAS 会「成功地」改错对象，这正是 ABA。所以要先等 hazard/epoch 证明没人再引用，才能归还内存。</span>内存序：发布节点内容先于把指针 CAS 进表，见<a href="/cs/atomic-rmw">原子 RMW</a>。<span class="marginnote">这句翻译成白话：先写好信纸（把新节点的字段填完），再投进邮筒（把指针 CAS 挂上链）——读的人一旦看见指针，就必然读到填写完整的节点，不会看到半封信。</span></p><p>不要在本课写可运行的竞态 exploit；只写结构。</p>',4)),(e(),r(n,null,{default:E(()=>[i(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%8F%92%E5%85%A5%2042%EF%BC%9A%E5%85%88%E5%AE%9A%E4%BD%8D%E5%90%84%E5%B1%82%E5%89%8D%E9%A9%B1%22%5D%20--%3E%20S1%5B%22%E7%AC%AC%E4%B8%80%E6%AD%A5%EF%BC%9A%E6%96%B0%E8%8A%82%E7%82%B9%E5%9C%A8%E5%BA%95%E5%B1%82%E4%B8%B2%E5%A5%BD%20next%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E7%AC%AC%E4%BA%8C%E6%AD%A5%EF%BC%9A%E4%BB%8E%E4%BD%8E%E5%B1%82%E5%88%B0%E9%AB%98%E5%B1%82%E9%80%90%E5%B1%82%20CAS%20%E5%89%8D%E9%A9%B1%E7%9A%84%20next%22%5D%0A%20%20S2%20--%3E%20V%5B%22%E4%B8%AD%E9%97%B4%E6%80%81%EF%BC%9A%E6%9F%A5%E6%89%BE%E8%80%85%E5%8F%AF%E8%83%BD%E5%8F%AA%E5%9C%A8%E5%BA%95%E5%B1%82%E7%9C%8B%E8%A7%81%2042%22%5D%0A%20%20V%20--%3E%20OK%5B%22%E9%93%BE%E4%BB%8D%E6%9C%89%E5%BA%8F%E4%BB%8D%E5%8F%AF%E8%BE%BE%EF%BC%9A%E6%9F%A5%E6%89%BE%E5%AE%B9%E5%BF%8D%E5%8D%8A%E6%88%90%E5%93%81%22%5D%0A%20%20S2%20--%3E%20FAIL%5B%22%E6%9F%90%E5%B1%82%20CAS%20%E5%A4%B1%E8%B4%A5%EF%BC%9A%E5%89%8D%E9%A9%B1%E5%B7%B2%E5%8F%98%EF%BC%8C%E9%87%8D%E6%96%B0%E5%AE%9A%E4%BD%8D%E5%86%8D%E8%AF%95%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把完整无锁证明写完，不引入 skip list 的确定性变体。堆的可并合同与跳表无关：下一课左偏树与配对堆，为优先队列减键与合并做准备。</p><p>后课默认：并发有序映射可用跳表。可合并堆从左偏与配对开始。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>并发跳表：查找只读，更新 CAS 或分层锁。</li><li>删除常分标记与摘链；注意 ABA 与回收。</li><li>下一课转向可并堆，不是再一层跳表。</li><li>出处：Pugh, 1990；Herlihy and Shavit。</li></ul>',5))])}const u=o(p,[["render",d]]);export{m as __pageData,u as default};
